-- Aprenda se Divertindo · 102 · Simulados de 07 e 08/11/2026
-- Rode depois do 101-trilha-policial-15.sql. Cole tudo no SQL Editor e clique em Run.
-- 1) Reabre o Simulado 1 de Saúde e o Simulado 1 do Enem (as mesmas provas) para o fim de semana de 07 e 08/11.
--    Se ninguém fez a prova, ela só muda de data. Se alguém já fez, ela é copiada para a nova data
--    e a antiga sai do ar, para o gabarito não vazar antes da nova aplicação.
-- 2) Cria o Simulado 1 da trilha Fiscal: 100 questões de A a E, estilo FGV, 4 horas de prova.
--    Português 12, Raciocínio Lógico 8, Informática 6, Constitucional 8, Administrativo 8, Tributário 14,
--    Contabilidade 12, AFO 8, Auditoria 6, Economia 6, Estatística 6, Legislação Aduaneira 6.
--    Gabarito equilibrado: 20 questões com cada letra. Gabarito comentado na segunda, 09/11, às 0h.
-- Rodar de novo não duplica nada.

do $$
declare t text; v record; nid bigint;
begin
  foreach t in array array['saude','enem'] loop
    if exists (select 1 from public.simulados where trilha = t and data = date '2026-11-08') then
      raise notice '%: já existe simulado em 08/11, nada a fazer.', t;
      continue;
    end if;
    select * into v from public.simulados where trilha = t and data < date '2026-11-08' order by data desc limit 1;
    if v.id is null then raise notice '%: nenhum simulado anterior encontrado.', t; continue; end if;
    if not exists (select 1 from public.simulado_respostas r where r.simulado_id = v.id) then
      update public.simulados set data = date '2026-11-08', publicado = true where id = v.id;
      raise notice '%: simulado % movido para 08/11.', t, v.id;
    else
      insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
      values (t, date '2026-11-08', v.titulo, v.estilo, v.duracao_min, true) returning id into nid;
      insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
      select nid, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao
        from public.simulado_questoes where simulado_id = v.id;
      update public.simulados set publicado = false where id = v.id;
      raise notice '%: simulado copiado para 08/11 (novo id %); o anterior saiu do ar.', t, nid;
    end if;
  end loop;
end $$;

do $$
declare sid bigint; lista jsonb := $q$[{"materia": "port", "texto_base": "A discussão sobre a carga tributária no Brasil costuma ser feita como se o problema fosse apenas de tamanho. Fala-se em quanto o Estado arrecada, raramente em como arrecada. No entanto, a forma de cobrar pesa tanto quanto o volume cobrado. Um sistema que concentra a tributação sobre o consumo, por exemplo, tende a onerar mais quem ganha menos, porque essas pessoas gastam quase toda a renda em bens e serviços. O imposto embutido no preço do arroz é o mesmo para o rico e para o pobre; o esforço para pagá-lo, não.\n\nPor isso, reformas tributárias que se limitam a simplificar a cobrança, embora necessárias, não resolvem sozinhas a questão da justiça fiscal. Simplificar reduz custos e litígios, o que já é muito; mas um sistema pode ser simples e, ainda assim, regressivo. A pergunta decisiva continua sendo quem paga a conta — e em que proporção.", "enunciado": "Segundo o texto, a tributação concentrada no consumo tende a onerar mais quem ganha menos porque", "opcoes": ["essas pessoas gastam em consumo quase toda a renda que recebem.", "os mais ricos são isentos dos tributos embutidos nos preços.", "a simplificação da cobrança encarece os alimentos básicos.", "o imposto sobre o consumo tem alíquotas maiores para os mais pobres.", "o volume arrecadado sobre o consumo é maior que o da renda."], "gabarito": 0, "explicacao": "O texto afirma que essas pessoas “gastam quase toda a renda em bens e serviços”."}, {"materia": "port", "texto_base": "A discussão sobre a carga tributária no Brasil costuma ser feita como se o problema fosse apenas de tamanho. Fala-se em quanto o Estado arrecada, raramente em como arrecada. No entanto, a forma de cobrar pesa tanto quanto o volume cobrado. Um sistema que concentra a tributação sobre o consumo, por exemplo, tende a onerar mais quem ganha menos, porque essas pessoas gastam quase toda a renda em bens e serviços. O imposto embutido no preço do arroz é o mesmo para o rico e para o pobre; o esforço para pagá-lo, não.\n\nPor isso, reformas tributárias que se limitam a simplificar a cobrança, embora necessárias, não resolvem sozinhas a questão da justiça fiscal. Simplificar reduz custos e litígios, o que já é muito; mas um sistema pode ser simples e, ainda assim, regressivo. A pergunta decisiva continua sendo quem paga a conta — e em que proporção.", "enunciado": "No trecho “o esforço para pagá-lo, não”, há omissão de", "opcoes": ["um complemento verbal que o leitor deduz apenas do título.", "um termo já expresso na oração anterior (“é o mesmo”).", "um advérbio de tempo que indicaria quando se paga.", "um sujeito que não aparece em nenhuma parte do texto.", "uma conjunção conclusiva que ligaria as duas orações."], "gabarito": 1, "explicacao": "Elipse (zeugma): “o esforço para pagá-lo não é o mesmo”."}, {"materia": "port", "texto_base": "A discussão sobre a carga tributária no Brasil costuma ser feita como se o problema fosse apenas de tamanho. Fala-se em quanto o Estado arrecada, raramente em como arrecada. No entanto, a forma de cobrar pesa tanto quanto o volume cobrado. Um sistema que concentra a tributação sobre o consumo, por exemplo, tende a onerar mais quem ganha menos, porque essas pessoas gastam quase toda a renda em bens e serviços. O imposto embutido no preço do arroz é o mesmo para o rico e para o pobre; o esforço para pagá-lo, não.\n\nPor isso, reformas tributárias que se limitam a simplificar a cobrança, embora necessárias, não resolvem sozinhas a questão da justiça fiscal. Simplificar reduz custos e litígios, o que já é muito; mas um sistema pode ser simples e, ainda assim, regressivo. A pergunta decisiva continua sendo quem paga a conta — e em que proporção.", "enunciado": "No segundo parágrafo, a conjunção “embora” introduz ideia de", "opcoes": ["conformidade.", "concessão.", "finalidade.", "condição.", "causa."], "gabarito": 1, "explicacao": "“Embora necessárias”: admite-se um fato que não impede a afirmação principal."}, {"materia": "port", "texto_base": "A discussão sobre a carga tributária no Brasil costuma ser feita como se o problema fosse apenas de tamanho. Fala-se em quanto o Estado arrecada, raramente em como arrecada. No entanto, a forma de cobrar pesa tanto quanto o volume cobrado. Um sistema que concentra a tributação sobre o consumo, por exemplo, tende a onerar mais quem ganha menos, porque essas pessoas gastam quase toda a renda em bens e serviços. O imposto embutido no preço do arroz é o mesmo para o rico e para o pobre; o esforço para pagá-lo, não.\n\nPor isso, reformas tributárias que se limitam a simplificar a cobrança, embora necessárias, não resolvem sozinhas a questão da justiça fiscal. Simplificar reduz custos e litígios, o que já é muito; mas um sistema pode ser simples e, ainda assim, regressivo. A pergunta decisiva continua sendo quem paga a conta — e em que proporção.", "enunciado": "De acordo com o texto, a simplificação do sistema tributário", "opcoes": ["elimina a tributação sobre o consumo de bens básicos.", "resolve o problema da carga, que é apenas de tamanho.", "é necessária, mas não basta para garantir a justiça fiscal.", "deve ser evitada, pois aumenta a regressividade da cobrança.", "torna o sistema progressivo, por reduzir custos e litígios."], "gabarito": 2, "explicacao": "“Um sistema pode ser simples e, ainda assim, regressivo.”"}, {"materia": "port", "texto_base": "A discussão sobre a carga tributária no Brasil costuma ser feita como se o problema fosse apenas de tamanho. Fala-se em quanto o Estado arrecada, raramente em como arrecada. No entanto, a forma de cobrar pesa tanto quanto o volume cobrado. Um sistema que concentra a tributação sobre o consumo, por exemplo, tende a onerar mais quem ganha menos, porque essas pessoas gastam quase toda a renda em bens e serviços. O imposto embutido no preço do arroz é o mesmo para o rico e para o pobre; o esforço para pagá-lo, não.\n\nPor isso, reformas tributárias que se limitam a simplificar a cobrança, embora necessárias, não resolvem sozinhas a questão da justiça fiscal. Simplificar reduz custos e litígios, o que já é muito; mas um sistema pode ser simples e, ainda assim, regressivo. A pergunta decisiva continua sendo quem paga a conta — e em que proporção.", "enunciado": "Em “Fala-se em quanto o Estado arrecada”, a palavra “se” é", "opcoes": ["pronome apassivador, como em “vende-se”.", "pronome reflexivo.", "índice de indeterminação do sujeito.", "conjunção integrante.", "parte integrante do verbo."], "gabarito": 2, "explicacao": "“Falar em” é transitivo indireto; com “se”, o sujeito fica indeterminado."}, {"materia": "port", "texto_base": "A discussão sobre a carga tributária no Brasil costuma ser feita como se o problema fosse apenas de tamanho. Fala-se em quanto o Estado arrecada, raramente em como arrecada. No entanto, a forma de cobrar pesa tanto quanto o volume cobrado. Um sistema que concentra a tributação sobre o consumo, por exemplo, tende a onerar mais quem ganha menos, porque essas pessoas gastam quase toda a renda em bens e serviços. O imposto embutido no preço do arroz é o mesmo para o rico e para o pobre; o esforço para pagá-lo, não.\n\nPor isso, reformas tributárias que se limitam a simplificar a cobrança, embora necessárias, não resolvem sozinhas a questão da justiça fiscal. Simplificar reduz custos e litígios, o que já é muito; mas um sistema pode ser simples e, ainda assim, regressivo. A pergunta decisiva continua sendo quem paga a conta — e em que proporção.", "enunciado": "No texto, um sistema “regressivo” é aquele em que", "opcoes": ["os tributos recaem apenas sobre o patrimônio.", "as alíquotas aumentam à medida que a renda do contribuinte cresce.", "o contribuinte recebe de volta parte do que pagou.", "a arrecadação total diminui de um ano para o outro.", "o tributo pesa proporcionalmente mais para quem tem menos."], "gabarito": 4, "explicacao": "É o oposto do sistema progressivo, em que as alíquotas sobem com a renda."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase correta quanto à concordância verbal.", "opcoes": ["Devem haver mudanças na lei.", "Fazem cinco anos que a lei mudou.", "Houveram mudanças na lei.", "Deve haver mudanças na lei.", "Existe muitas mudanças na lei."], "gabarito": 3, "explicacao": "“Haver” (existir) é impessoal, e o auxiliar fica no singular; “existir” concorda com o sujeito."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase em que o acento grave está empregado corretamente.", "opcoes": ["A empresa pagou à vista e à prazo.", "O contribuinte foi à pé até a repartição.", "O fiscal referiu-se à norma revogada.", "Entregou o auto de infração à ele.", "O auditor começou à analisar os livros."], "gabarito": 2, "explicacao": "Referir-se a + a norma. Não há crase antes de verbo, de pronome pessoal, de palavra masculina."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase correta quanto à regência verbal.", "opcoes": ["O servidor obedeceu o regulamento interno.", "Os sócios preferem mais pagar do que discutir o débito.", "O contribuinte aspira o parcelamento da dívida.", "O auditor esqueceu-se o prazo do recurso.", "O contribuinte aspira ao parcelamento da dívida."], "gabarito": 4, "explicacao": "“Aspirar”, no sentido de desejar, exige a preposição “a”."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase corretamente pontuada.", "opcoes": ["Os auditores, voltaram ao trabalho após a longa greve.", "Os auditores, que estavam em greve, voltaram ao trabalho.", "Os auditores que estavam, em greve voltaram ao trabalho.", "Os auditores que, estavam em greve voltaram ao trabalho.", "Os auditores voltaram, ao trabalho, após a greve."], "gabarito": 1, "explicacao": "A oração adjetiva explicativa vem entre vírgulas; não se separa o sujeito do verbo."}, {"materia": "port", "texto_base": "", "enunciado": "Em “Se a empresa recolher o imposto, não haverá multa”, a oração “Se a empresa recolher o imposto” é", "opcoes": ["subordinada adverbial concessiva.", "subordinada adverbial causal.", "subordinada substantiva objetiva direta.", "subordinada adverbial condicional.", "coordenada sindética conclusiva."], "gabarito": 3, "explicacao": "“Se” introduz condição."}, {"materia": "port", "texto_base": "", "enunciado": "Assinale a frase em que a colocação do pronome segue a norma-padrão.", "opcoes": ["Quando informaram-nos, já era tarde.", "Me informaram o prazo ontem.", "Ninguém informou-nos o prazo.", "Ninguém nos informou o prazo.", "Tinha informado-nos do prazo."], "gabarito": 3, "explicacao": "Pronome indefinido negativo atrai o pronome (próclise); não se inicia frase com pronome oblíquo átono."}, {"materia": "rl", "texto_base": "", "enunciado": "Se o auditor revisa o processo, então encontra erro. O auditor não encontrou erro. Logo,", "opcoes": ["nada se pode concluir sobre a revisão.", "o auditor encontrou erro em outro processo.", "o auditor revisou o processo.", "o processo não tinha erro algum.", "o auditor não revisou o processo."], "gabarito": 4, "explicacao": "Modus tollens: de P → Q e ¬Q, conclui-se ¬P."}, {"materia": "rl", "texto_base": "", "enunciado": "A negação de “Todo contribuinte paga em dia ou é multado” é:", "opcoes": ["Todo contribuinte não paga em dia e é multado.", "Algum contribuinte não paga em dia ou não é multado.", "Algum contribuinte paga em dia e é multado.", "Nenhum contribuinte paga em dia nem é multado.", "Algum contribuinte não paga em dia e não é multado."], "gabarito": 4, "explicacao": "Nega-se o “todo” com “algum… não” e aplica-se De Morgan à disjunção."}, {"materia": "rl", "texto_base": "", "enunciado": "A proposição “Se há fraude, então há autuação” é equivalente a:", "opcoes": ["Se há autuação, então há fraude.", "Se não há autuação, então não há fraude.", "Não há fraude e há autuação.", "Há fraude e não há autuação.", "Se não há fraude, então não há autuação."], "gabarito": 1, "explicacao": "Contrapositiva: P → Q ≡ ¬Q → ¬P."}, {"materia": "rl", "texto_base": "", "enunciado": "A alíquota de um imposto passou de 12% para 15%. O aumento percentual da alíquota foi de", "opcoes": ["25%.", "20%.", "30%.", "3%.", "15%."], "gabarito": 0, "explicacao": "(15 − 12) / 12 = 0,25."}, {"materia": "rl", "texto_base": "", "enunciado": "Aplicando R$ 10.000,00 a juros compostos de 2% ao mês, o montante ao fim de 3 meses é de", "opcoes": ["R$ 10.600,00.", "R$ 10.612,00.", "R$ 10.624,32.", "R$ 10.612,08.", "R$ 10.606,08."], "gabarito": 3, "explicacao": "10.000 × 1,02³ = 10.000 × 1,061208."}, {"materia": "rl", "texto_base": "", "enunciado": "Uma comissão de 3 auditores será formada a partir de 5 homens e 4 mulheres, com pelo menos uma mulher. O número de comissões possíveis é", "opcoes": ["74.", "40.", "70.", "84.", "64."], "gabarito": 0, "explicacao": "Total C(9,3) = 84, menos as só de homens C(5,3) = 10: 74."}, {"materia": "rl", "texto_base": "", "enunciado": "Num lote de 10 declarações, 3 têm erro. Sorteando 2 sem reposição, a probabilidade de nenhuma ter erro é", "opcoes": ["1/3.", "49/100.", "3/10.", "8/15.", "7/15."], "gabarito": 4, "explicacao": "7/10 × 6/9 = 42/90 = 7/15."}, {"materia": "rl", "texto_base": "", "enunciado": "Ana, Beto e Caio fiscalizam ICMS, ISS e IPTU, um tributo cada. Ana não fiscaliza ISS, e Caio fiscaliza IPTU. Logo,", "opcoes": ["Ana fiscaliza IPTU.", "Beto fiscaliza ISS.", "Caio fiscaliza ICMS.", "Beto fiscaliza ICMS.", "Ana fiscaliza ISS."], "gabarito": 1, "explicacao": "Caio fica com IPTU; Ana não fica com ISS, então fica com ICMS; sobra ISS para Beto."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, a fórmula =ARRED(2,567;2) retorna", "opcoes": ["2,6.", "3.", "2,57.", "2,567.", "2,56."], "gabarito": 2, "explicacao": "Arredonda para duas casas decimais."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, a fórmula =CONT.SE(A1:A10;\">100\") retorna", "opcoes": ["a posição da primeira célula maior que 100.", "a média das células com valor acima de 100.", "a soma dos valores maiores que 100 existentes no intervalo.", "o número de células do intervalo com valor acima de 100.", "o maior valor do intervalo, se ele passar de 100."], "gabarito": 3, "explicacao": "CONT.SE conta as células que atendem ao critério."}, {"materia": "inf", "texto_base": "", "enunciado": "Em SQL, a cláusula usada para filtrar grupos depois do GROUP BY é", "opcoes": ["HAVING.", "WHERE.", "ORDER BY.", "DISTINCT.", "JOIN."], "gabarito": 0, "explicacao": "WHERE filtra linhas antes do agrupamento; HAVING filtra os grupos."}, {"materia": "inf", "texto_base": "", "enunciado": "O princípio da segurança da informação que garante que o dado não foi alterado indevidamente é a", "opcoes": ["autenticidade.", "disponibilidade.", "confidencialidade.", "integridade.", "irretratabilidade."], "gabarito": 3, "explicacao": "Integridade: a informação permanece exata e completa."}, {"materia": "inf", "texto_base": "", "enunciado": "Um e-mail que imita a Receita Federal e pede que o contribuinte clique num link para “regularizar o CPF” é exemplo de", "opcoes": ["ransomware.", "worm.", "phishing.", "keylogger.", "negação de serviço."], "gabarito": 2, "explicacao": "Engenharia social para obter dados por mensagem falsa."}, {"materia": "inf", "texto_base": "", "enunciado": "No Excel, a referência que mantém fixa apenas a coluna, ao copiar a fórmula, é", "opcoes": ["A$1.", "$A$1.", "#A1.", "A1.", "$A1."], "gabarito": 4, "explicacao": "O cifrão antes da letra fixa a coluna."}, {"materia": "const", "texto_base": "", "enunciado": "São objetivos fundamentais da República Federativa do Brasil, entre outros:", "opcoes": ["o pluralismo político e a não intervenção.", "a soberania, a cidadania e a dignidade da pessoa humana.", "os valores sociais do trabalho e da livre-iniciativa.", "a independência nacional e a prevalência dos direitos humanos.", "erradicar a pobreza e reduzir as desigualdades."], "gabarito": 4, "explicacao": "Art. 3º da CF. As demais são fundamentos (art. 1º) ou princípios das relações internacionais (art. 4º)."}, {"materia": "const", "texto_base": "", "enunciado": "Compete à União instituir imposto sobre", "opcoes": ["grandes fortunas, nos termos de lei complementar.", "a transmissão causa mortis e doação.", "a propriedade predial e territorial urbana.", "a transmissão onerosa de imóveis entre pessoas vivas.", "a propriedade de veículos automotores."], "gabarito": 0, "explicacao": "Art. 153, VII, da CF. Os demais são estaduais ou municipais."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição, é vedada a edição de medida provisória sobre", "opcoes": ["abertura de crédito extraordinário em calamidade.", "organização administrativa do Poder Executivo.", "política de preços de combustíveis.", "instituição ou aumento de impostos, em qualquer caso.", "direito penal, processual penal e processual civil."], "gabarito": 4, "explicacao": "Art. 62, § 1º, I, b, da CF. MP pode instituir ou aumentar impostos, observadas as regras do § 2º."}, {"materia": "const", "texto_base": "", "enunciado": "O Tribunal de Contas da União", "opcoes": ["substitui a CGU no controle interno do Executivo.", "julga em definitivo as contas anuais do Presidente.", "auxilia o Congresso Nacional no controle externo.", "é subordinado ao Ministério da Fazenda.", "integra o Poder Judiciário e julga crimes de responsabilidade."], "gabarito": 2, "explicacao": "Art. 71 da CF."}, {"materia": "const", "texto_base": "", "enunciado": "As contas prestadas anualmente pelo Presidente da República são julgadas pelo", "opcoes": ["Supremo Tribunal Federal.", "Tribunal de Contas da União.", "Congresso Nacional.", "Controladoria-Geral da União.", "Senado Federal, apenas."], "gabarito": 2, "explicacao": "Art. 49, IX, da CF. O TCU emite parecer prévio (art. 71, I)."}, {"materia": "const", "texto_base": "", "enunciado": "A iniciativa das leis do plano plurianual, das diretrizes orçamentárias e do orçamento anual cabe", "opcoes": ["ao chefe do Poder Executivo.", "ao Congresso Nacional.", "ao Tribunal de Contas.", "ao Senado Federal.", "ao Ministro da Fazenda, por portaria."], "gabarito": 0, "explicacao": "Art. 165 da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Constituição, as administrações tributárias da União, dos estados, do DF e dos municípios", "opcoes": ["terão recursos prioritários para suas atividades.", "poderão criar tributos por meio de portarias.", "terão autonomia financeira em relação ao Executivo.", "receberão 10% fixos da receita de todos os impostos.", "serão subordinadas diretamente ao Poder Judiciário."], "gabarito": 0, "explicacao": "Art. 37, XXII, da CF."}, {"materia": "const", "texto_base": "", "enunciado": "Pela Emenda Constitucional 132/2023, o Imposto sobre Bens e Serviços (IBS) é de competência", "opcoes": ["exclusiva dos municípios.", "compartilhada entre estados, DF e municípios.", "exclusiva da União.", "da União e dos estados, em conjunto, por convênio.", "exclusiva dos estados e do DF."], "gabarito": 1, "explicacao": "Art. 156-A da CF. A CBS é da União."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021, a modalidade obrigatória para a compra de bens e serviços comuns é o", "opcoes": ["pregão.", "leilão.", "diálogo competitivo.", "concurso.", "credenciamento."], "gabarito": 0, "explicacao": "Art. 6º, XLI, e art. 29 da Lei 14.133/2021."}, {"materia": "adm", "texto_base": "", "enunciado": "Na Lei 14.133/2021, a contratação direta de compras em razão do baixo valor é hipótese de", "opcoes": ["inexigibilidade de licitação.", "dispensa de licitação.", "licitação deserta.", "pregão eletrônico.", "credenciamento."], "gabarito": 1, "explicacao": "Art. 75, II, da Lei 14.133/2021."}, {"materia": "adm", "texto_base": "", "enunciado": "A inexigibilidade de licitação ocorre quando", "opcoes": ["o valor fica abaixo do limite legal.", "há inviabilidade de competição.", "nenhum interessado aparece na licitação.", "a Administração quer contratar mais rápido.", "há guerra ou grave perturbação da ordem."], "gabarito": 1, "explicacao": "Art. 74 da Lei 14.133/2021."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 8.429/1992, receber vantagem econômica para tolerar a exploração de jogo de azar é ato de improbidade que", "opcoes": ["importa enriquecimento ilícito.", "atenta contra os princípios da Administração.", "decorre de conduta apenas culposa.", "concede indevidamente benefício tributário.", "causa prejuízo ao erário."], "gabarito": 0, "explicacao": "Art. 9º, V, da Lei 8.429/1992."}, {"materia": "adm", "texto_base": "", "enunciado": "O ato pelo qual a Administração extingue outro ato por ilegalidade chama-se", "opcoes": ["cassação.", "contraposição.", "revogação.", "caducidade.", "anulação."], "gabarito": 4, "explicacao": "A revogação extingue ato válido por conveniência; a anulação, ato ilegal."}, {"materia": "adm", "texto_base": "", "enunciado": "Pela Lei 9.784/1999, não pode ser objeto de delegação", "opcoes": ["a edição de atos de caráter normativo.", "a expedição de certidões e declarações.", "a prática de atos de rotina do órgão.", "a instrução dos processos administrativos.", "a prática de atos de gestão de pessoal."], "gabarito": 0, "explicacao": "Art. 13 da Lei 9.784/1999, ao lado da decisão de recursos e das matérias de competência exclusiva."}, {"materia": "adm", "texto_base": "", "enunciado": "A autarquia é pessoa jurídica de direito", "opcoes": ["privado, cuja criação é autorizada por lei.", "público, mas sem personalidade própria.", "público, criada por decreto do Executivo.", "privado, constituída por contrato social.", "público, criada por lei específica."], "gabarito": 4, "explicacao": "Art. 37, XIX, da CF."}, {"materia": "adm", "texto_base": "", "enunciado": "O princípio incluído no art. 37 da Constituição pela EC 19/1998, que exige da Administração o melhor resultado com o menor custo, é o da", "opcoes": ["economicidade.", "eficiência.", "razoabilidade.", "publicidade.", "moralidade."], "gabarito": 1, "explicacao": "EC 19/1998 (reforma administrativa)."}, {"materia": "trib", "texto_base": "", "enunciado": "Pelo CTN, o lançamento é atividade administrativa", "opcoes": ["privativa da autoridade, vinculada e obrigatória.", "facultativa, conforme a conveniência e a oportunidade do fisco.", "que pode ser feita por qualquer servidor.", "discricionária da autoridade fiscal.", "privativa do contribuinte, na declaração."], "gabarito": 0, "explicacao": "Art. 142 do CTN."}, {"materia": "trib", "texto_base": "", "enunciado": "Não se sujeita à anterioridade nonagesimal, entre outros,", "opcoes": ["o imposto de renda.", "o ICMS.", "o IPVA, na fixação da alíquota.", "o IPI.", "as contribuições da seguridade social."], "gabarito": 0, "explicacao": "Art. 150, § 1º, da CF. O IR só observa a anterioridade anual."}, {"materia": "trib", "texto_base": "", "enunciado": "Não se sujeita à anterioridade anual, mas se sujeita à nonagesimal,", "opcoes": ["o IPTU.", "o imposto de renda.", "o IPI.", "o ITR.", "o ITBI."], "gabarito": 2, "explicacao": "Art. 150, § 1º, da CF."}, {"materia": "trib", "texto_base": "", "enunciado": "Pelo CTN, a obrigação acessória, pelo simples fato de não ser cumprida,", "opcoes": ["suspende a exigibilidade do crédito tributário principal.", "passa a ser crime contra a ordem tributária.", "deixa de poder ser exigida pelo fisco.", "converte-se em obrigação principal quanto à penalidade.", "extingue a obrigação principal correspondente."], "gabarito": 3, "explicacao": "Art. 113, § 3º, do CTN."}, {"materia": "trib", "texto_base": "", "enunciado": "São causas de suspensão da exigibilidade do crédito tributário, entre outras:", "opcoes": ["pagamento, compensação, transação e remissão.", "prescrição, decadência e conversão do depósito em renda da Fazenda.", "moratória, depósito integral, recursos e parcelamento.", "isenção e anistia.", "lançamento, inscrição em dívida ativa e protesto."], "gabarito": 2, "explicacao": "Art. 151 do CTN. As outras são extinção (art. 156) e exclusão (art. 175)."}, {"materia": "trib", "texto_base": "", "enunciado": "São causas de exclusão do crédito tributário:", "opcoes": ["moratória e parcelamento.", "compensação e pagamento.", "remissão e transação.", "isenção e anistia.", "prescrição e decadência."], "gabarito": 3, "explicacao": "Art. 175 do CTN."}, {"materia": "trib", "texto_base": "", "enunciado": "Em regra (CTN, art. 173, I), o direito de a Fazenda constituir o crédito extingue-se em 5 anos, contados", "opcoes": ["do vencimento da última parcela do tributo declarado.", "da inscrição do débito em dívida ativa pela procuradoria.", "da notificação do lançamento ao contribuinte ou ao responsável tributário.", "do primeiro dia do exercício seguinte ao que o lançamento poderia ser feito.", "da data do fato gerador, em qualquer caso, inclusive com dolo."], "gabarito": 3, "explicacao": "Art. 173, I, do CTN."}, {"materia": "trib", "texto_base": "", "enunciado": "No tributo sujeito a lançamento por homologação, se o contribuinte não declara nem paga, a decadência é contada, segundo o STJ,", "opcoes": ["pelo art. 168, a partir da extinção do crédito.", "pelo art. 174, a partir da constituição definitiva.", "pelo art. 173, I, do CTN.", "pelo art. 150, § 4º, a partir do fato gerador.", "pelo prazo de 10 anos fixado em lei ordinária."], "gabarito": 2, "explicacao": "Súmula 555 do STJ."}, {"materia": "trib", "texto_base": "", "enunciado": "A ação de cobrança do crédito tributário prescreve em 5 anos, contados", "opcoes": ["do ajuizamento da execução fiscal.", "da ocorrência do fato gerador.", "da constituição definitiva do crédito.", "do primeiro dia do exercício seguinte.", "da inscrição em dívida ativa."], "gabarito": 2, "explicacao": "Art. 174 do CTN."}, {"materia": "trib", "texto_base": "", "enunciado": "Pelo CTN, são solidariamente obrigadas as pessoas que", "opcoes": ["tenham interesse comum na situação do fato gerador.", "sejam sócias da empresa devedora, em qualquer caso.", "integrem o mesmo grupo econômico, de forma automática.", "tenham sido indicadas pelo contribuinte na declaração.", "residam no mesmo endereço do contribuinte."], "gabarito": 0, "explicacao": "Art. 124, I, do CTN."}, {"materia": "trib", "texto_base": "", "enunciado": "A responsabilidade pessoal do sócio-gerente pelos tributos da sociedade, prevista no art. 135 do CTN, exige", "opcoes": ["a falência regular da sociedade empresária.", "atos com excesso de poderes ou infração de lei, contrato ou estatuto.", "a existência de dívida acima de 500 salários mínimos.", "a mera condição de sócio, ainda que sem nenhum poder de gestão na empresa.", "o simples inadimplemento do tributo pela sociedade."], "gabarito": 1, "explicacao": "Súmula 430 do STJ: o simples inadimplemento não gera a responsabilidade."}, {"materia": "trib", "texto_base": "", "enunciado": "Pela Constituição, o ICMS é um imposto", "opcoes": ["cumulativo, que incide em cascata sobre todas as etapas da cadeia produtiva.", "cobrado apenas na importação de mercadorias vindas do exterior.", "de alíquotas fixadas pela União, com seletividade obrigatória em todos os estados.", "não cumulativo, compensando-se o devido com o cobrado nas operações anteriores.", "imune em todas as operações internas com combustíveis e energia."], "gabarito": 3, "explicacao": "Art. 155, § 2º, I, da CF."}, {"materia": "trib", "texto_base": "", "enunciado": "Pela EC 132/2023, a Contribuição sobre Bens e Serviços (CBS) substitui, ao longo da transição,", "opcoes": ["o IPTU e o IPVA.", "o IPI e o IOF.", "o ICMS e o ISS.", "o PIS e a Cofins.", "o IR e a CSLL."], "gabarito": 3, "explicacao": "O IBS substitui ICMS e ISS."}, {"materia": "trib", "texto_base": "", "enunciado": "Pelo CTN, o fato gerador da obrigação principal é", "opcoes": ["a inscrição do contribuinte no cadastro fiscal do ente.", "o ato de lançamento praticado pela autoridade administrativa competente.", "a situação definida em lei como necessária e suficiente.", "qualquer situação que obrigue a prestar informações ao fisco.", "a situação prevista em regulamento do órgão fazendário."], "gabarito": 2, "explicacao": "Art. 114 do CTN."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma empresa compra mercadorias a prazo por R$ 10.000,00. O efeito no balanço é", "opcoes": ["redução do ativo (caixa) e aumento do passivo (fornecedores).", "aumento do ativo e do patrimônio líquido.", "aumento do ativo (estoques) e do passivo (fornecedores).", "aumento do passivo e redução do patrimônio líquido.", "permuta entre contas do ativo, sem efeito no passivo."], "gabarito": 2, "explicacao": "Fato permutativo: ativo e passivo aumentam no mesmo valor, sem alterar o patrimônio líquido."}, {"materia": "cont", "texto_base": "", "enunciado": "Estoque inicial de R$ 20.000,00, compras de R$ 50.000,00 e estoque final de R$ 15.000,00. O CMV é de", "opcoes": ["R$ 45.000,00.", "R$ 55.000,00.", "R$ 85.000,00.", "R$ 65.000,00.", "R$ 35.000,00."], "gabarito": 1, "explicacao": "CMV = EI + C − EF = 20.000 + 50.000 − 15.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Uma máquina custou R$ 120.000,00, tem valor residual de R$ 20.000,00 e vida útil de 10 anos. Pelo método linear, a depreciação anual é de", "opcoes": ["R$ 14.000,00.", "R$ 12.000,00.", "R$ 11.000,00.", "R$ 10.000,00.", "R$ 8.000,00."], "gabarito": 3, "explicacao": "(120.000 − 20.000) / 10."}, {"materia": "cont", "texto_base": "", "enunciado": "Ativo circulante de R$ 300.000,00 e passivo circulante de R$ 200.000,00. O índice de liquidez corrente é", "opcoes": ["0,67.", "1,5.", "1,2.", "3,0.", "2,0."], "gabarito": 1, "explicacao": "300.000 / 200.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Ativo circulante de R$ 300.000,00, estoques de R$ 100.000,00 e passivo circulante de R$ 200.000,00. O índice de liquidez seca é", "opcoes": ["1,5.", "0,67.", "1,0.", "0,5.", "2,0."], "gabarito": 2, "explicacao": "(300.000 − 100.000) / 200.000."}, {"materia": "cont", "texto_base": "", "enunciado": "Pela Lei 6.404/1976, 5% do lucro líquido vão para a reserva legal até que ela atinja", "opcoes": ["10% do capital social.", "20% do capital social.", "50% do patrimônio líquido.", "30% do capital social.", "100% do capital social."], "gabarito": 1, "explicacao": "Art. 193 da Lei 6.404/1976."}, {"materia": "cont", "texto_base": "", "enunciado": "Pelo regime de competência, a receita é reconhecida", "opcoes": ["no fim do exercício, junto com as despesas.", "somente quando recebida em dinheiro.", "quando ganha, independentemente do recebimento.", "sempre na data de assinatura do contrato de venda.", "quando o cliente paga a nota fiscal."], "gabarito": 2, "explicacao": "Estrutura Conceitual e Lei 6.404/1976."}, {"materia": "cont", "texto_base": "", "enunciado": "Em 1º de outubro, a empresa paga antecipadamente R$ 12.000,00 por 12 meses de aluguel. Em 31 de dezembro, a despesa de aluguel reconhecida no exercício é de", "opcoes": ["R$ 9.000,00.", "R$ 3.000,00.", "zero.", "R$ 12.000,00.", "R$ 1.000,00."], "gabarito": 1, "explicacao": "Três meses (outubro a dezembro) × R$ 1.000,00. O restante fica no ativo como despesa antecipada."}, {"materia": "cont", "texto_base": "", "enunciado": "Na DRE, o lucro bruto é obtido por", "opcoes": ["receita líquida menos o custo das mercadorias vendidas.", "receita bruta menos despesas operacionais.", "lucro operacional menos imposto de renda.", "receita bruta menos deduções, impostos e despesas financeiras.", "receita líquida menos despesas administrativas."], "gabarito": 0, "explicacao": "Lei 6.404/1976, art. 187."}, {"materia": "cont", "texto_base": "", "enunciado": "A conta Capital a Integralizar é classificada como", "opcoes": ["receita do exercício.", "ativo circulante.", "ativo não circulante.", "redutora do patrimônio líquido.", "passivo não circulante (exigível a longo prazo)."], "gabarito": 3, "explicacao": "Representa a parte do capital subscrito ainda não paga pelos sócios."}, {"materia": "cont", "texto_base": "", "enunciado": "Pelo CPC 27, o ativo imobilizado é mensurado, no reconhecimento inicial, pelo", "opcoes": ["custo.", "valor de mercado na data do balanço.", "valor justo, sempre.", "valor residual.", "valor recuperável."], "gabarito": 0, "explicacao": "CPC 27, item 15."}, {"materia": "cont", "texto_base": "", "enunciado": "Vendas de R$ 200.000,00, CMV de R$ 120.000,00 e despesas operacionais de R$ 50.000,00. O resultado operacional é de", "opcoes": ["R$ 30.000,00.", "R$ 70.000,00.", "R$ 150.000,00.", "R$ 50.000,00.", "R$ 80.000,00."], "gabarito": 0, "explicacao": "Lucro bruto 80.000 − despesas 50.000."}, {"materia": "afo", "texto_base": "", "enunciado": "Pela Lei 4.320/1964, os estágios da despesa pública são", "opcoes": ["empenho, arrecadação e recolhimento.", "lançamento, arrecadação e recolhimento.", "fixação, licitação e contrato.", "empenho, liquidação e pagamento.", "previsão, lançamento e arrecadação."], "gabarito": 3, "explicacao": "Arts. 58 a 65 da Lei 4.320/1964."}, {"materia": "afo", "texto_base": "", "enunciado": "Os estágios da receita pública são", "opcoes": ["empenho, liquidação, pagamento e recolhimento ao caixa.", "lançamento, liquidação, arrecadação e pagamento.", "previsão, lançamento, arrecadação e recolhimento.", "previsão, empenho, liquidação e recolhimento.", "fixação, empenho, arrecadação e pagamento."], "gabarito": 2, "explicacao": "Doutrina e Manual de Contabilidade Aplicada ao Setor Público."}, {"materia": "afo", "texto_base": "", "enunciado": "Pela LRF, o limite da despesa total com pessoal da União é de", "opcoes": ["60% da receita corrente líquida.", "40% da receita corrente líquida.", "49% da receita corrente líquida.", "54% da receita corrente líquida.", "50% da receita corrente líquida."], "gabarito": 4, "explicacao": "Art. 19, I, da LC 101/2000. Estados e municípios: 60%."}, {"materia": "afo", "texto_base": "", "enunciado": "Pela LRF, se a despesa com pessoal passar de 95% do limite, o Poder fica proibido de, entre outras medidas,", "opcoes": ["pagar precatórios judiciais já vencidos.", "conceder aumento ou reajuste, salvo as exceções legais.", "arrecadar e fiscalizar os tributos de sua competência.", "pagar a remuneração dos servidores ativos.", "repor aposentados nas áreas de educação, saúde e segurança."], "gabarito": 1, "explicacao": "Art. 22, parágrafo único, da LC 101/2000."}, {"materia": "afo", "texto_base": "", "enunciado": "Restos a pagar processados são despesas", "opcoes": ["liquidadas e pagas dentro do próprio exercício financeiro.", "empenhadas e liquidadas, mas não pagas até 31/12.", "empenhadas, mas ainda não liquidadas.", "pagas antecipadamente ao fornecedor.", "previstas na LOA, mas não empenhadas."], "gabarito": 1, "explicacao": "Art. 36 da Lei 4.320/1964."}, {"materia": "afo", "texto_base": "", "enunciado": "O crédito adicional destinado a despesas urgentes e imprevisíveis, como guerra ou calamidade pública, é o", "opcoes": ["extraordinário.", "suplementar.", "especial.", "ordinário.", "emergencial."], "gabarito": 0, "explicacao": "Art. 167, § 3º, da CF e art. 41, III, da Lei 4.320/1964."}, {"materia": "afo", "texto_base": "", "enunciado": "O crédito especial destina-se a despesas", "opcoes": ["de restos a pagar de exercícios anteriores.", "de cobertura de déficit de caixa do mês.", "que reforçam uma dotação já existente.", "urgentes e imprevisíveis, como as de guerra ou calamidade.", "sem dotação orçamentária específica."], "gabarito": 4, "explicacao": "Art. 41, II, da Lei 4.320/1964."}, {"materia": "afo", "texto_base": "", "enunciado": "Pela LRF, a receita corrente líquida é apurada somando-se as receitas", "opcoes": ["do primeiro semestre do exercício.", "do mês de referência e dos onze meses anteriores.", "do mês de referência, apenas.", "do exercício anterior inteiro, sem nenhuma dedução ou ajuste.", "dos últimos quatro exercícios, em média."], "gabarito": 1, "explicacao": "Art. 2º, § 3º, da LC 101/2000."}, {"materia": "aud", "texto_base": "", "enunciado": "Pela NBC TA 200, o auditor busca obter, sobre as demonstrações contábeis, segurança", "opcoes": ["razoável, não absoluta.", "nenhuma, pois apenas descreve os fatos.", "total, desde que não haja fraude.", "absoluta, examinando todas as transações.", "limitada aos controles internos testados."], "gabarito": 0, "explicacao": "Há limitações inerentes à auditoria."}, {"materia": "aud", "texto_base": "", "enunciado": "O risco de auditoria é a combinação do risco de distorção relevante com o risco de", "opcoes": ["inerente.", "amostragem.", "controle.", "detecção.", "fraude."], "gabarito": 3, "explicacao": "O risco de distorção relevante já engloba os riscos inerente e de controle."}, {"materia": "aud", "texto_base": "", "enunciado": "Quando as distorções são relevantes e generalizadas nas demonstrações, o auditor emite", "opcoes": ["abstenção de opinião.", "parágrafo de ênfase.", "opinião adversa.", "opinião sem ressalva.", "opinião com ressalva."], "gabarito": 2, "explicacao": "NBC TA 705."}, {"materia": "aud", "texto_base": "", "enunciado": "Quando o auditor não consegue obter evidência suficiente e os possíveis efeitos são relevantes e generalizados, ele emite", "opcoes": ["opinião com ressalva.", "parágrafo de outros assuntos.", "opinião adversa.", "opinião sem ressalva.", "abstenção de opinião."], "gabarito": 4, "explicacao": "NBC TA 705."}, {"materia": "aud", "texto_base": "", "enunciado": "A evidência obtida por confirmação externa (circularização) é, em geral,", "opcoes": ["suficiente sozinha, sem outros procedimentos.", "menos confiável que a gerada pela própria entidade.", "dispensável quando o controle interno é forte.", "obtida apenas por indagação verbal aos empregados da entidade.", "mais confiável que a gerada internamente pela entidade."], "gabarito": 4, "explicacao": "NBC TA 500 e 505."}, {"materia": "aud", "texto_base": "", "enunciado": "Pela NBC TA 240, a responsabilidade primária pela prevenção e detecção de fraude é", "opcoes": ["do auditor independente contratado.", "do Conselho Federal de Contabilidade e dos conselhos regionais.", "da administração e dos responsáveis pela governança.", "da auditoria interna, exclusivamente.", "do contador da empresa, apenas."], "gabarito": 2, "explicacao": "NBC TA 240, item 4."}, {"materia": "eco", "texto_base": "", "enunciado": "Uma elasticidade-preço da demanda maior que 1, em módulo, indica demanda", "opcoes": ["inelástica.", "elástica.", "perfeitamente inelástica.", "de elasticidade unitária.", "anelástica."], "gabarito": 1, "explicacao": "A quantidade varia proporcionalmente mais que o preço."}, {"materia": "eco", "texto_base": "", "enunciado": "O preço de um bem sobe 10% e a quantidade demandada cai 5%. A elasticidade-preço da demanda, em módulo, é", "opcoes": ["5,0.", "0,05.", "2,0.", "1,0.", "0,5."], "gabarito": 4, "explicacao": "5% / 10%."}, {"materia": "eco", "texto_base": "", "enunciado": "É medida de política monetária contracionista", "opcoes": ["a redução do depósito compulsório.", "a compra de títulos públicos pelo Banco Central.", "a redução de impostos.", "o aumento da taxa Selic.", "o aumento dos gastos do governo."], "gabarito": 3, "explicacao": "Juros maiores reduzem a demanda agregada."}, {"materia": "eco", "texto_base": "", "enunciado": "Pela ótica da despesa, Y = C + I + G + (X − M). Se C = 600, I = 200, G = 250, X = 100 e M = 150, o PIB é", "opcoes": ["1.050.", "950.", "1.100.", "1.000.", "1.300."], "gabarito": 3, "explicacao": "600 + 200 + 250 + 100 − 150."}, {"materia": "eco", "texto_base": "", "enunciado": "Em concorrência perfeita, no longo prazo, as empresas obtêm", "opcoes": ["lucro extraordinário permanente.", "o mesmo lucro de um monopólio.", "preço acima do custo médio.", "prejuízo permanente.", "lucro econômico zero."], "gabarito": 4, "explicacao": "A livre entrada elimina o lucro extraordinário."}, {"materia": "eco", "texto_base": "", "enunciado": "O bem cuja demanda aumenta quando a renda do consumidor aumenta é um bem", "opcoes": ["complementar.", "de Giffen.", "substituto.", "inferior.", "normal."], "gabarito": 4, "explicacao": "No bem inferior, a demanda cai com o aumento da renda."}, {"materia": "est", "texto_base": "", "enunciado": "A média aritmética de 4, 6, 8, 10 e 12 é", "opcoes": ["9.", "6.", "8.", "10.", "7."], "gabarito": 2, "explicacao": "40 / 5."}, {"materia": "est", "texto_base": "", "enunciado": "A mediana de 3, 7, 1, 9, 5 e 11 é", "opcoes": ["9.", "7.", "5.", "8.", "6."], "gabarito": 4, "explicacao": "Ordenando: 1, 3, 5, 7, 9, 11; média dos centrais (5 + 7) / 2."}, {"materia": "est", "texto_base": "", "enunciado": "A variância populacional de 2, 4 e 6 é", "opcoes": ["8.", "√8.", "2.", "8/3.", "4."], "gabarito": 3, "explicacao": "Média 4; desvios ao quadrado 4, 0 e 4; 8/3. A amostral seria 4."}, {"materia": "est", "texto_base": "", "enunciado": "Uma variável tem média 50 e desvio padrão 10. O coeficiente de variação é", "opcoes": ["20%.", "50%.", "10%.", "500%.", "5%."], "gabarito": 0, "explicacao": "10 / 50."}, {"materia": "est", "texto_base": "", "enunciado": "Somando 5 a todos os valores de um conjunto, o desvio padrão", "opcoes": ["diminui 5 unidades.", "não se altera.", "fica multiplicado por 5.", "aumenta 25 unidades.", "aumenta 5 unidades."], "gabarito": 1, "explicacao": "Somar uma constante desloca a média, mas não a dispersão."}, {"materia": "est", "texto_base": "", "enunciado": "A probabilidade de uma declaração cair na malha fina é 0,2. Em 3 declarações independentes, a probabilidade de exatamente uma cair na malha é", "opcoes": ["0,6.", "0,128.", "0,488.", "0,2.", "0,384."], "gabarito": 4, "explicacao": "3 × 0,2 × 0,8² = 0,384."}, {"materia": "adua", "texto_base": "", "enunciado": "O imposto de importação é de competência", "opcoes": ["dos estados.", "do Distrito Federal, apenas.", "da União.", "dos municípios.", "compartilhada entre União e estados."], "gabarito": 2, "explicacao": "Art. 153, I, da CF."}, {"materia": "adua", "texto_base": "", "enunciado": "Com alíquota ad valorem, a base de cálculo do imposto de importação é", "opcoes": ["o valor do frete internacional, apenas.", "o preço de venda no mercado interno.", "o valor da nota fiscal de saída.", "o preço de revenda ao consumidor.", "o valor aduaneiro da mercadoria."], "gabarito": 4, "explicacao": "Regulamento Aduaneiro, art. 75."}, {"materia": "adua", "texto_base": "", "enunciado": "O regime que permite a entrada de bens no país, com suspensão de tributos e por prazo determinado, para depois retornarem ao exterior, é a", "opcoes": ["trânsito aduaneiro.", "admissão temporária.", "entreposto aduaneiro.", "exportação temporária.", "drawback."], "gabarito": 1, "explicacao": "Regulamento Aduaneiro, art. 353."}, {"materia": "adua", "texto_base": "", "enunciado": "O drawback é um regime aduaneiro especial que", "opcoes": ["permite armazenar mercadorias com tributos suspensos.", "suspende tributos de bens que vêm para feiras e eventos.", "autoriza o transporte de mercadorias entre recintos.", "desonera insumos usados na produção de bens exportados.", "isenta de tributos a bagagem de viajantes."], "gabarito": 3, "explicacao": "Incentivo à exportação."}, {"materia": "adua", "texto_base": "", "enunciado": "Importar mercadoria proibida configura o crime de", "opcoes": ["receptação.", "peculato.", "sonegação fiscal.", "contrabando.", "descaminho."], "gabarito": 3, "explicacao": "Art. 334-A do CP. O descaminho envolve mercadoria permitida com tributo iludido."}, {"materia": "adua", "texto_base": "", "enunciado": "A zona secundária aduaneira compreende", "opcoes": ["o restante do território aduaneiro, com águas territoriais e espaço aéreo.", "os portos, aeroportos e pontos de fronteira alfandegados pela Receita.", "somente os portos secos instalados no interior.", "apenas as zonas de processamento de exportação.", "as áreas de livre comércio e a Zona Franca de Manaus."], "gabarito": 0, "explicacao": "Regulamento Aduaneiro, art. 3º, II."}]$q$::jsonb;
begin
  insert into public.simulados (trilha, data, titulo, estilo, duracao_min, publicado)
  values ('fiscal', date '2026-11-08', 'Simulado 1 · Fiscal', 'FGV', 240, true)
  on conflict (trilha, data) do update set titulo = excluded.titulo, estilo = excluded.estilo, duracao_min = excluded.duracao_min
  returning id into sid;
  if exists (select 1 from public.simulado_respostas r where r.simulado_id = sid) then
    raise notice 'Simulado já iniciado por alguém: questões mantidas.';
  else
    delete from public.simulado_questoes where simulado_id = sid;
    insert into public.simulado_questoes (simulado_id, ordem, materia, texto_base, enunciado, opcoes, gabarito, explicacao)
    select sid, e.n, e.v ->> 'materia', nullif(e.v ->> 'texto_base', ''), e.v ->> 'enunciado', e.v -> 'opcoes', (e.v ->> 'gabarito')::smallint, e.v ->> 'explicacao'
      from jsonb_array_elements(lista) with ordinality e(v, n);
    update public.simulados set publicado = true where id = sid;
  end if;
end $$;

select s.id, s.trilha, s.data - 1 as abre_sabado, s.data as fecha_domingo, s.titulo, s.estilo, s.publicado, count(q.ordem) as questoes
  from public.simulados s left join public.simulado_questoes q on q.simulado_id = s.id
 where s.data >= date '2026-11-01'
 group by s.id order by s.data, s.trilha;
